public class JitDemo {
    public static void main(String[] args) {
        long start = System.currentTimeMillis();
        long sum = 0;
        // Running enough iterations to trigger C1 and C2 compilation
        for (int i = 0; i < 500_000_000; i++) {
            sum += compute(i);
        }
        System.out.println("Time taken: " + (System.currentTimeMillis() - start) + "ms, Sum: " + sum);
    }

    private static long compute(int val) {
        return val * 31L;
    }
}
